// core/shared-types/resolve-conflict: settles the dependency version of a consumer whose update
// merge (or pull) conflicted. Only conflict blocks of `package.json` whose two sides differ
// solely by the dependency line are rewritten — to the version published earlier in the run, else
// the consumer's own (current-branch) value; every other block, file and marker stays byte for
// byte. `package-lock.json` is taken from the current-branch side, regenerated by `npm i` and
// staged, but only once `package.json` holds no conflict marker. The flow is idempotent: it is
// rerun after the developer has edited, so the lockfile is regenerated as soon as they are done.
// Core never names the module: the dependency and file path come from the consumer.
import { dirname, join, posix } from 'node:path';
import type { GitPort } from '../ports/git.js';
import type { RestartPort } from '../ports/restart.js';
import type { AutoResolveResult } from '../scripts/group-update.js';
import type { DependencyConsumerConfig } from './list-consumers.js';

function normalizeRel(path: string): string {
  return posix.normalize(path.replace(/\\/g, '/')).replace(/^\.\//, '');
}

function escapeRegExp(text: string): string {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function dependencyLinePattern(dependency: string): RegExp {
  return new RegExp(`^\\s*"${escapeRegExp(JSON.stringify(dependency).slice(1, -1))}"\\s*:\\s*"(?:[^"\\\\]|\\\\.)*"\\s*,?\\s*$`);
}

function stripEol(line: string): string {
  return line.replace(/\r?\n$/, '');
}

const MARKER_PATTERN = /^(<{7}|>{7})( |\r?$)/m;

export function hasConflictMarkers(content: string): boolean {
  return MARKER_PATTERN.test(content);
}

export interface BlockRewrite {
  content: string;
  // Blocks rewritten to a single resolved line set.
  rewritten: number;
  // A block holds the dependency line next to other differing lines (or on one side only).
  mixed: boolean;
  // A conflict block mentioning the dependency line never closes.
  unterminated?: boolean;
}

// Rewrites each conflict block whose sides differ only by the dependency line. `version`
// undefined keeps the current-branch (`ours`) value as it is. Nothing is rewritten when any
// block mentioning the dependency is mixed.
export function rewriteDependencyBlocks(content: string, dependency: string, version: string | undefined): BlockRewrite {
  const linePattern = dependencyLinePattern(dependency);
  const valuePattern = new RegExp(`("${escapeRegExp(JSON.stringify(dependency).slice(1, -1))}"\\s*:\\s*)"(?:[^"\\\\]|\\\\.)*"`);
  const lines = content.split(/(?<=\n)/);
  const output: string[] = [];
  let rewritten = 0;
  let mixed = false;
  let unterminated = false;
  let index = 0;
  while (index < lines.length) {
    const line = lines[index] as string;
    if (!stripEol(line).startsWith('<<<<<<< ') && stripEol(line) !== '<<<<<<<') {
      output.push(line);
      index += 1;
      continue;
    }
    // Collect one block: ours, optional diff3 base, theirs.
    const ours: string[] = [];
    const theirs: string[] = [];
    let section: 'ours' | 'base' | 'theirs' = 'ours';
    let cursor = index + 1;
    let closed = false;
    while (cursor < lines.length) {
      const text = stripEol(lines[cursor] as string);
      if (text.startsWith('||||||| ') || text === '|||||||') {
        section = 'base';
      } else if (text === '=======') {
        section = 'theirs';
      } else if (text.startsWith('>>>>>>> ') || text === '>>>>>>>') {
        closed = true;
        break;
      } else if (section === 'ours') {
        ours.push(lines[cursor] as string);
      } else if (section === 'theirs') {
        theirs.push(lines[cursor] as string);
      }
      cursor += 1;
    }
    const raw = lines.slice(index, closed ? cursor + 1 : lines.length);
    index = closed ? cursor + 1 : lines.length;
    const oursAt = ours.map((entry, at) => (linePattern.test(stripEol(entry)) ? at : -1)).filter((at) => at >= 0);
    const theirsAt = theirs.map((entry, at) => (linePattern.test(stripEol(entry)) ? at : -1)).filter((at) => at >= 0);
    if (!closed) {
      if (raw.some((entry) => linePattern.test(stripEol(entry)))) {
        unterminated = true;
      }
      output.push(...raw);
      continue;
    }
    if (oursAt.length === 0 && theirsAt.length === 0) {
      output.push(...raw);
      continue;
    }
    if (oursAt.length !== 1 || theirsAt.length !== 1) {
      mixed = true;
      output.push(...raw);
      continue;
    }
    const oursRest = ours.filter((_entry, at) => at !== oursAt[0]).map(stripEol);
    const theirsRest = theirs.filter((_entry, at) => at !== theirsAt[0]).map(stripEol);
    if (oursRest.length !== theirsRest.length || oursRest.some((entry, at) => entry !== theirsRest[at])) {
      mixed = true;
      output.push(...raw);
      continue;
    }
    const resolved = ours.map((entry, at) =>
      at === oursAt[0] && version !== undefined ? entry.replace(valuePattern, (_match, prefix: string) => `${prefix}${JSON.stringify(version)}`) : entry,
    );
    output.push(...resolved);
    rewritten += 1;
  }
  if (mixed || unterminated) {
    return { content, rewritten: 0, mixed, ...(unterminated ? { unterminated } : {}) };
  }
  return { content: output.join(''), rewritten, mixed: false };
}

export interface AutoResolveSharedTypesParams {
  git: GitPort;
  restart: RestartPort;
  repoPath: string;
  consumer: DependencyConsumerConfig;
  // The version published earlier in the run; absent, the consumer's own value is kept.
  preferredVersion?: string;
}

export async function autoResolveSharedTypesConflict(params: AutoResolveSharedTypesParams): Promise<AutoResolveResult> {
  const { git, restart, repoPath, consumer, preferredVersion } = params;
  const packageRel = normalizeRel(consumer.packageJsonPath);
  const lockRel = normalizeRel(join(dirname(consumer.packageJsonPath), 'package-lock.json'));

  const unmerged = await git.listUnmergedPaths(repoPath);
  if (!unmerged.ok) {
    return { touched: false, issue: `Cannot list the conflicted files: ${unmerged.error.message}` };
  }
  const conflicted = new Set(unmerged.data.map(normalizeRel));
  const packageUnmerged = conflicted.has(packageRel);
  const lockUnmerged = conflicted.has(lockRel);
  if (!packageUnmerged && !lockUnmerged) {
    return { touched: false };
  }

  let touched = false;
  let packageSettled = true;
  // package.json is ours to re-stage: not conflicted, or settled and staged by this resolver.
  let packageOwned = !packageUnmerged;
  if (packageUnmerged) {
    const read = await git.readWorktreeFile(repoPath, packageRel);
    if (!read.ok) {
      return { touched: false, issue: `Cannot read ${packageRel}: ${read.error.message}` };
    }
    if (hasConflictMarkers(read.data)) {
      const rewrite = rewriteDependencyBlocks(read.data, consumer.dependency, preferredVersion);
      if (rewrite.unterminated === true) {
        return { touched: false, issue: `${packageRel} has an unterminated conflict block around the ${consumer.dependency} line — resolve it by hand.` };
      }
      if (rewrite.mixed) {
        return {
          touched: false,
          issue: `The ${consumer.dependency} line of ${packageRel} sits in a conflict block that also differs elsewhere — resolve it by hand.`,
        };
      }
      if (rewrite.rewritten === 0) {
        if (!read.data.split(/\r?\n/).some((line) => dependencyLinePattern(consumer.dependency).test(line))) {
          return { touched: false, issue: `The ${consumer.dependency} line was not found in ${packageRel} — resolve it by hand.` };
        }
        packageSettled = false;
      } else {
        packageSettled = !hasConflictMarkers(rewrite.content);
        packageOwned = packageSettled;
        const written = await git.writeResolvedFile(repoPath, packageRel, rewrite.content, { stage: packageSettled });
        if (!written.ok) {
          return { touched: false, issue: `Cannot write ${packageRel}: ${written.error.message}` };
        }
        touched = true;
      }
    }
  }

  if (lockUnmerged && packageSettled) {
    // Never overwrite a lockfile the developer already resolved: take our side only while it
    // still carries conflict markers.
    const lockContent = await git.readWorktreeFile(repoPath, lockRel);
    if (!lockContent.ok) {
      return { touched, issue: `Cannot read ${lockRel}: ${lockContent.error.message}` };
    }
    if (hasConflictMarkers(lockContent.data)) {
      const taken = await git.checkoutSide(repoPath, lockRel, 'ours');
      if (!taken.ok) {
        return { touched, issue: `Cannot take ${lockRel} from the current branch: ${taken.error.message}` };
      }
    }
    const installed = await restart.run(join(repoPath, dirname(consumer.packageJsonPath)), 'npm i');
    if (!installed.ok) {
      return { touched: true, issue: `npm i failed while regenerating ${lockRel}: ${installed.error.message}` };
    }
    const toStage = [lockRel];
    // npm may reformat package.json: re-stage it when we own its resolution.
    if (packageOwned) {
      const dirty = await git.listDirtyPaths(repoPath);
      if (dirty.ok && dirty.data.map(normalizeRel).includes(packageRel)) {
        toStage.push(packageRel);
      }
    }
    const staged = await git.stagePaths(repoPath, toStage);
    if (!staged.ok) {
      return { touched: true, issue: `Cannot stage ${toStage.join(', ')}: ${staged.error.message}` };
    }
    touched = true;
  }
  return { touched };
}
